param(
    [string]$RepoRoot = (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
    [string]$ExtractedRoot = 'C:\Users\uriah\AppData\Local\Temp\{68379049-6E6C-4478-A2C5-EF7B77ED7E38}',
    [string]$SourceDir = 'C:\Mac\Home\Downloads\forms\1701Av2018'
)

$ErrorActionPreference = 'Stop'
$formId = '1701a-v2018'
$revision = '2018-01-01'
$packageVersion = '7.9.6.0'
$htaPath = Join-Path $ExtractedRoot 'forms\BIR-Form1701A.hta'
$shared1701Path = Join-Path $ExtractedRoot 'js\lib\1701.js'
$plainPath = Join-Path $SourceDir '00000000000000-1701A-122025.xml'
$livePlainPath = 'C:\eBIRForms\savefile\00000000000000-1701A-122025.xml'
$encryptedCandidates = @(Get-ChildItem -LiteralPath $SourceDir -File | Where-Object { $_.Name -like '00000000000000-1701A-122025#*#.xml' })
if ($encryptedCandidates.Count -ne 1) { throw "Expected one encrypted companion; found $($encryptedCandidates.Count)." }
$encryptedPath = $encryptedCandidates[0].FullName
$pdfPath = Join-Path $SourceDir '1701A Jan 2018 v5 with rates.pdf'
$outDir = Join-Path $RepoRoot 'rules\forms\1701a-v2018'
$fixtureDir = Join-Path $outDir 'fixtures'
foreach ($path in @($htaPath,$shared1701Path,$plainPath,$livePlainPath,$encryptedPath,$pdfPath)) { if (-not(Test-Path -LiteralPath $path)) { throw "Missing source: $path" } }
New-Item -ItemType Directory -Force -Path $fixtureDir | Out-Null

function Write-Json([string]$Path,$Value){[IO.File]::WriteAllText($Path,(($Value|ConvertTo-Json -Depth 50)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false))}
function Write-Utf8([string]$Path,[string]$Value){[IO.File]::WriteAllText($Path,$Value,[Text.UTF8Encoding]::new($false))}
function Get-Attr([string]$Tag,[string]$Name){$m=[regex]::Match($Tag,('(?i)\b{0}\s*=\s*([''"])(.*?)\1'-f[regex]::Escape($Name)));if($m.Success){$m.Groups[2].Value}else{$null}}
function Get-HashText([string[]]$Lines){$sha=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(($Lines-join"`n"))))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function Asset([string]$Id,[string]$Kind,[string]$Path,[string]$Binding){$item=Get-Item -LiteralPath $Path;[pscustomobject][ordered]@{asset_id=$Id;kind=$Kind;path=$Path;sha256=(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant();size=$item.Length;revision_binding=$Binding}}

$expectedHashes=@{
    hta='c85f8f1e13e4752549cb2886bc598a0be4cf8b67a709d9a913d09d22f087de1b'
    plain='8080c5a9bb0118da9001e87bc4c68ebacfe39899594bdfc264ad676974bf8c7f'
    live='f14637f0efdf5c78ab286a1170325c0304519067d8e675aa011a3a160ddf5793'
    encrypted='2f77216933ad96fce43bd2da82e782e15e74d987c4159ff50f1dc60a5e74bb57'
    pdf='8d492eabc6da2088cf9a55084488b192def5cc415048f607142c8bce1b72bfb8'
    shared='1e32cd9110be7b87aec51e2ef365366a3637a008f4bd8f980ecf9cc5b70edd24'
}
foreach ($pair in @(@($htaPath,'hta'),@($plainPath,'plain'),@($livePlainPath,'live'),@($encryptedPath,'encrypted'),@($pdfPath,'pdf'),@($shared1701Path,'shared'))) {
    $actual = (Get-FileHash -LiteralPath $pair[0] -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne $expectedHashes[$pair[1]]) { throw "Hash changed: $($pair[0])" }
}
$pdfBytes = [IO.File]::ReadAllBytes($pdfPath)
if ([Text.Encoding]::ASCII.GetString($pdfBytes[0..4]) -ne '%PDF-') { throw 'Official PDF magic mismatch.' }

$hta=[IO.File]::ReadAllText($htaPath)
$plain=[IO.File]::ReadAllText($plainPath)
$livePlain=[IO.File]::ReadAllText($livePlainPath)
function Save-Keys([string]$Text){@([regex]::Matches($Text,'<div>(?<key>[^=<>]+)=(?<value>[^<]*?)\k<key>=</div>')|ForEach-Object{$_.Groups['key'].Value})}
$keys=Save-Keys $plain;$liveKeys=Save-Keys $livePlain
if ($keys.Count -ne 194 -or ($keys | Sort-Object -Unique).Count -ne 194) { throw "Expected 194 source-save keys; found $($keys.Count)." }
if ((Compare-Object ($keys | Sort-Object) ($liveKeys | Sort-Object)).Count -ne 0) { throw 'Reviewed and live plaintext save key sets differ.' }
if ($plain -notmatch '<div>frm1701A:txtVersion=11112018frm1701A:txtVersion=</div>') { throw 'Version marker mismatch.' }

$formMatch=[regex]::Match($hta,'(?is)<form\b[^>]*(?:id|name)\s*=\s*["'']frmMain["''][^>]*>(?<body>.*?)</form>');if(-not$formMatch.Success){throw 'frmMain not found.'}
$formBody=$formMatch.Groups['body'].Value;$formOffset=$formMatch.Groups['body'].Index;$scriptRanges=@([regex]::Matches($formBody,'(?is)<script\b.*?</script>'))
$controls=@();$ordinal=0
foreach ($m in [regex]::Matches($formBody,'(?is)<(input|select|textarea|button)\b[^>]*>')) {
    $inside = $false
    foreach ($range in $scriptRanges) {
        if ($m.Index -ge $range.Index -and $m.Index -lt ($range.Index + $range.Length)) { $inside = $true; break }
    }
    if ($inside) { continue }
    $ordinal++
    $tag = $m.Value
    $element = $m.Groups[1].Value.ToLowerInvariant()
    $kind = if ($element -eq 'input') { Get-Attr $tag 'type' } else { $element }
    if (-not $kind) { $kind = 'text' }
    $controls += [pscustomobject][ordered]@{
        ordinal = $ordinal; id = Get-Attr $tag 'id'; name = Get-Attr $tag 'name'; element = $element
        control_kind = $kind.ToLowerInvariant(); source_line = 1 + [regex]::Matches($hta.Substring(0,$formOffset+$m.Index),"`n").Count
        value = Get-Attr $tag 'value'; maxlength = Get-Attr $tag 'maxlength'
        disabled = $tag -match '(?i)\bdisabled(?:\s*=|\s|>)'; readonly = $tag -match '(?i)\breadonly(?:\s*=|\s|>)'
    }
}
$serializable = @($controls | Where-Object { $_.control_kind -in @('text','select','select-one','radio','checkbox') })
if ($controls.Count -ne 233 -or $serializable.Count -ne 193) { throw "Expected 233 controls/193 static candidates; found $($controls.Count)/$($serializable.Count)." }
$controlById = @{}
foreach ($c in $controls) { if ($c.id -and -not $controlById.ContainsKey($c.id)) { $controlById[$c.id] = $c } }

$required=@('frm1701A:txtYear','frm1701A:txtTIN1','frm1701A:txtTIN2','frm1701A:txtTIN3','frm1701A:txtBranchCode','frm1701A:txtRDOCode','frm1701A:txtTaxpayerName','frm1701A:txtAddress','frm1701A:txtBirthDate','frm1701A:txtZipCode')
$computed='(?i)^frm1701A:txt(20|21|22|24|28|29|30|38|39|40|44|45|46|49|52|53|55|56|64|65)[AB]?$'
function Meta([string]$Key,$Control,[bool]$Family){$page=$null;$item=$null;$logical='string';$status='optional';$enum=[object[]]@();$norm=[string[]]@();$isComputed=$false;$calc=$null;if($Key-match'(?i)^frm1701A:txt(?<n>\d+)'){$item=$Matches.n}elseif($Key-match'(?i)Item(?<n>\d+)'){$item=$Matches.n};if($Key-match'(?i)(opt|checkbox|Refund)'){$logical='boolean';$enum=[object[]]@('true','false')}elseif($Key-match'(?i)(TIN|BranchCode|RDOCode|ATC)'){$logical='code'}elseif($Key-match'(?i)Email'){$logical='email-string'}elseif($Key-match'(?i)(Tel|Contact)'){$logical='phone-string'}elseif($Key-match'(?i)(BirthDate|Date)'){$logical='date-string';$norm=[string[]]@('MM/DD/YYYY where checked')}elseif($Key-match'(?i)Month'){$logical='month'}elseif($Key-match'(?i)Year'){$logical='integer'}elseif($Key-match'(?i)(txt\d+|Amount|Tax|Income|Sales|Revenue|Receipts|Deduct|Loss|Cost|Payment|Credit|Penalt|Surcharge|Interest|Compromise|Rate)'){$logical='whole-peso-amount';$norm=[string[]]@('NumWithComma','toFixed(0)','formatCurrency')};if($required-contains$Key){$status='required'};if($Key-match$computed){$status='computed';$isComputed=$true;$calc='See calculations.json'};if($Key-match'^(txtFinalFlag|txtEnroll|ebirOnline|driveSelectTPExport)'){$status='hidden'};if($Family){$status='conditional'};$constraints=[ordered]@{};if($Control-and$Control.maxlength){$constraints.max_length=[int]$Control.maxlength};if($Family){$constraints.index='N >= 1; no maximum is enforced by addRow().'};[pscustomobject]@{page=$page;item=$item;logical=$logical;status=$status;enum=$enum;norm=$norm;computed=$isComputed;calc=$calc;constraints=[pscustomobject]$constraints}}

$fields=[Collections.Generic.List[object]]::new()
foreach ($key in $keys) {
    $control = if ($controlById.ContainsKey($key)) { $controlById[$key] } else { $null }
    $meta = Meta $key $control $false
    $refs = @("xml-editable-v1#field:$key")
    if ($control) { $refs += "official-hta-runtime#control:L$($control.source_line)" }
    elseif ($key -match 'RDOCode') { $refs += 'official-hta-runtime#loadRdo:L2653-L2684' }
    else { $refs += 'official-hta-runtime#saveXML:L5216-L5368' }
    $fields.Add([pscustomobject][ordered]@{field_key=$key;serialized_key=$key;serialized_occurrence=1;label=$key;page=$meta.page;item_number=$meta.item;control_kind=if($control){$control.control_kind}else{'runtime-injected-control'};storage_type='string';logical_type=$meta.logical;required=$meta.status;required_when=$null;enabled_when=$null;visible_when=$null;default_value=if($control){$control.value}else{$null};empty_representation='';constraints=$meta.constraints;enum_values=$meta.enum;normalization=$meta.norm;computed=$meta.computed;calculation_id=$meta.calc;source_refs=$refs;confidence=if($control){'high'}else{'medium'};notes=@('Observed in both 194-key dummy plaintext saves; source values are excluded.')} )
}
$extra='frm1701A:txtAddress2';$ec=$controlById[$extra];$fields.Add([pscustomobject][ordered]@{field_key=$extra;serialized_key=$extra;serialized_occurrence=1;label='Registered address line 2';page=1;item_number='9';control_kind='text';storage_type='string';logical_type='string';required='optional';required_when=$null;enabled_when=$null;visible_when=$null;default_value=$ec.value;empty_representation='';constraints=[pscustomobject]@{};enum_values=[object[]]@();normalization=[string[]]@('escape() in encrypted/read-only save branch');computed=$false;calculation_id=$null;source_refs=@('xml-encrypted-v1#decrypted-field:frm1701A:txtAddress2',"official-hta-runtime#control:L$($ec.source_line)");confidence='high';notes=@('Encrypted-only 195th concrete key; no value is copied.')} )
$families=@(
    @{key='frm1701A:txtmodalPartIVADesc_{N>=1}C1';logical='string';lines='3843,4307-L4364'},@{key='frm1701A:txtmodalPartIVA_{N>=1}C2';logical='whole-peso-amount';lines='3844,4307-L4364'},@{key='frm1701A:txtmodalPartIVA_{N>=1}C3';logical='whole-peso-amount';lines='3845,4307-L4364'},
    @{key='frm1701A:txtmodalPartIVBDesc_{N>=1}C1';logical='string';lines='3873,4307-L4364'},@{key='frm1701A:txtmodalPartIVB_{N>=1}C2';logical='whole-peso-amount';lines='3874,4307-L4364'},@{key='frm1701A:txtmodalPartIVB_{N>=1}C3';logical='whole-peso-amount';lines='3875,4307-L4364'} )
foreach ($family in $families) {
    [string[]]$familyNormalization = if ($family.logical -eq 'whole-peso-amount') {
        @('whole-number key filter','round(this,2) despite whole-peso display')
    } else {
        @('capitalize on blur')
    }
    $fields.Add([pscustomobject][ordered]@{field_key=$family.key;serialized_key=$null;serialized_occurrence=$null;label="Runtime modal row field $($family.key)";page=$null;item_number=$null;control_kind='runtime-indexed-family';storage_type='string';logical_type=$family.logical;required='conditional';required_when='The corresponding Part IV.A or IV.B modal row N exists.';enabled_when='The applicable tax-rate schedule and party column are enabled.';visible_when='The modal is open or the row is retained in its repository table.';default_value=$null;empty_representation='';constraints=[pscustomobject]@{index='N >= 1; no runtime maximum'};enum_values=[object[]]@();normalization=$familyNormalization;computed=$false;calculation_id=$null;source_refs=@("official-hta-runtime#dynamic-id:L$($family.lines)",'official-hta-runtime#saveChanges:L3942-L4097');confidence='high';notes=@('Unbounded row family materialized inside frmMain and serialized by saveXML.')} )
}
if ($fields.Count -ne 201 -or ($fields.field_key | Sort-Object -Unique).Count -ne 201) { throw "Expected 201 unique fields/families; found $($fields.Count)." }
Write-Json (Join-Path $outDir 'fields.json') ([ordered]@{'$schema'='../../schema/fields.schema.json';schema_version='1.0.0';form_id=$formId;revision=$revision;field_count=$fields.Count;runtime_serializable_element_count=194;inventory_sha256=Get-HashText @($fields.field_key|Sort-Object);fields=$fields})
Write-Json (Join-Path $fixtureDir 'runtime-control-inventory-v796.json') ([ordered]@{schema_version='1.0.0';form_id=$formId;official_hta_sha256=$expectedHashes.hta;form_control_count=$controls.Count;static_serializer_candidate_count=$serializable.Count;reviewed_plaintext_key_count=194;reviewed_encrypted_key_count=195;runtime_modal_family_count=6;serializer_set_differences=[ordered]@{runtime_injected_observed=@('frm1701A:txtRDOCode','frm1701A:txtSpouseRDOCode');static_not_in_plain_snapshot=@('frm1701A:txtAddress2')};controls=$controls;dynamic_families=$families})

$decryptTool=Join-Path $RepoRoot 'rules\tools\audit-1701-encrypted-fields.ps1'
$decryptAudit=(& $decryptTool -SourceDir $SourceDir -FormId $formId -FilePattern '00000000000000-1701A-122025#*#.xml' -RedactedFileName '00000000000000-1701A-122025#email-redacted#.xml' -ExpectedCiphertextSha256 $expectedHashes.encrypted -ExpectedDecryptedSha256 '0bd7b97fcac70faee523c8a2841b8e95591d64c2d917f117b8728743ccdfa9b9' -ExpectedFieldCount 195 -ExpectedExtraField $extra -VersionField 'frm1701A:txtVersion' -ExpectedXmlVersion '11112018')-join[Environment]::NewLine
Write-Utf8 (Join-Path $fixtureDir 'encrypted-field-audit-v796.json') $decryptAudit
$functionTool=Join-Path $RepoRoot 'rules\tools\extract-hta-function-inventory.ps1'
Write-Utf8 (Join-Path $fixtureDir 'validation-function-inventory-v796.json') ((&$functionTool -HtaPath $htaPath -ControlPrefix 'frm1701A:' -NamePattern '(?i)valid|check|process|enable|disable|save|submit|final')-join[Environment]::NewLine)
Write-Utf8 (Join-Path $fixtureDir 'calculation-function-inventory-v796.json') ((&$functionTool -HtaPath $htaPath -ControlPrefix 'frm1701A:' -NamePattern '(?i)compute|calc|populate|sum|difference|product')-join[Environment]::NewLine)
Write-Utf8 (Join-Path $fixtureDir 'shared-1701-function-inventory-v796.json') ((&$functionTool -HtaPath $shared1701Path -ControlPrefix 'frm1701:' -NamePattern '(?i)populate|generate|process|compute|tax')-join[Environment]::NewLine)

$rules=[Collections.Generic.List[object]]::new()
function Rule([string]$Id,[string]$Phase,$Order,[string]$Condition,[string[]]$FieldKeys,[string]$Accepted,[string]$Rejected,$Message,[string[]]$Refs,[string]$Assessment='verified-correct',[string]$Official='The first active branch alerts and returns.',[string]$Recommended='Retain as a structured field error.',[string]$Confidence='high'){ $rules.Add([pscustomobject][ordered]@{rule_id=$Id;form_id=$formId;revision=$revision;phase=$Phase;order=$Order;condition=$Condition;fields=$FieldKeys;accepted_behavior=$Accepted;rejected_behavior=$Rejected;exact_message=$Message;source_refs=$Refs;evidence_type=@('source');assessment=$Assessment;official_behavior=$Official;recommended_app_behavior=$Recommended;confidence=$Confidence;unresolved_questions=@()}) }
Rule '1701a-save-001' 'save' 1 'Any taxpayer TIN segment or branch code is blank.' @('frm1701A:txtTIN1','frm1701A:txtTIN2','frm1701A:txtTIN3','frm1701A:txtBranchCode') 'All strings are nonblank.' 'Save is blocked.' 'Please enter a valid TIN number on Item 4.' @('official-hta-runtime#initialValidateBeforeSave:L5599-L5603') 'incorrect-official-behavior' 'Save checks nonblankness only.' 'Permit lossless drafts; require shape/checksum for finalization.'
